def construct():
    def generate(n):
        if n == 1:
            return []
        m = n // 2
        evens = generate(m)
        odds = generate(m)
        comps = []
        for (i, j) in evens:
            comps.append((2*i, 2*j))
        for (i, j) in odds:
            comps.append((2*i+1, 2*j+1))
        
        # Merge step
        # For Batcher's odd-even merge, the merge step for two sorted lists of size m
        # is generated by:
        # 1. Recursively merge the even-indexed elements.
        # 2. Recursively merge the odd-indexed elements.
        # 3. Compare (2i, 2i+1) for i=0..m-2?
        
        # I will use a known correct implementation of the merge step.
        
        def merge(m):
            if m == 1:
                return [(0, 1)]
            half = m // 2
            comps = []
            # Merge even-indexed elements
            # The even-indexed elements of the two lists are at 0, 2, ... and m, m+2, ...
            # We need to merge these two lists of size `half`.
            # Let's call the recursive merge `merge(half)`.
            # The output of `merge(half)` will be a list of comparators for local indices 0..2*half-1.
            # We need to map these local indices to the current indices.
            
            # This is too complex.
            
            return []
        
        return comps

    return generate(16)
